var resi_colors = [];
var saved_resi = {resi: null, color: null};


function focus_on_resi(resi) {

    // restore the color and backbone
    var colorObj = resi_colors[saved_resi.resi-2];
    colorObj.color = {r: saved_resi.color.r,
		      g: saved_resi.color.g,
		      b: saved_resi.color.b};
    colorObj.representation = "cartoon";

    // save and set the target resi
    colorObj = resi_colors[resi-2];
    saved_resi.resi = resi;
    saved_resi.color = {r: colorObj.color.r,
			g: colorObj.color.g,
			b: colorObj.color.b};
    colorObj.color = {r: 255, g: 255, b: 128};
    colorObj.representation = "ball-and-stick";

    viewerInstance.visual.select({data:resi_colors});
    viewerInstance.visual.focus([{start_residue_number: resi-10,
    				  end_residue_number: resi+6}]);
}


function scroll_and_focus(resi) {
    const element = document.getElementById(`id_${resi}`);
    if(element) {
	element.scrollIntoView();
    }
    focus_on_resi(resi);
}


function color_struct(acc, hotspoti){

    fetch("/color_api", {
        method: "POST",
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({'acc':acc})})
        .then(response => response.json())
        .then(data => {
	    let resL = data['data'];
	    resi_colors = [];
	    for (let i = 0; i < resL.length; i++) {
		var resi = parseInt(resL[i][0]);
		var rgb = resL[i][1];
		var colorObj = {
		    start_residue_number: resi,
		    end_residue_number: resi,
		    color: {
			r: rgb[0],
			g: rgb[1],
			b: rgb[2],
		    }
		};
		resi_colors.push(colorObj);
	    };
	    saved_resi.resi = resi_colors[0].start_residue_number;
	    saved_resi.color = {r: resi_colors[0].color.r,
				g: resi_colors[0].color.g,
				b: resi_colors[0].color.b};
	    viewerInstance.visual.select({data: resi_colors})
	    if( hotspoti !== null) {
		scroll_and_focus(hotspoti);
	    }
	})			 
	.catch((error) => {
            console.error('ERROR in color_api:', error);
        });
}


